'use strict';
// Original learning content authored for this programme. Not an ETS question bank.
const q = (prompt, options, correct, explanation) => ({ prompt, options, correct, explanation });
const units = [
  {
    title: 'Làm quen môi trường công sở', grammar: 'Cấu trúc câu và từ loại',
    goals: ['Nhận diện chủ ngữ, động từ và bổ ngữ trong câu công sở.', 'Đọc thông báo chào đón nhân viên và tìm đúng người phụ trách.', 'Giới thiệu công việc bằng 5–6 câu rõ ràng.'],
    notes: ['Một câu hoàn chỉnh thường có chủ ngữ và động từ đã chia: The assistant checks the schedule. Cụm The assistant in the lobby chưa phải câu vì thiếu động từ.', 'Sau mạo từ a/an/the thường là danh từ hoặc cụm danh từ: a careful assistant. Tính từ đứng trước danh từ; trạng từ mô tả hành động: The assistant works carefully.', 'Với động từ be, tính từ mô tả chủ ngữ: The office is quiet. Không dùng quietness nếu muốn nói văn phòng yên tĩnh.', 'Khi làm câu điền từ, xác định vị trí ngữ pháp trước, sau đó kiểm tra nghĩa. Đuôi -tion thường tạo danh từ; -ly thường tạo trạng từ nhưng friendly là tính từ.'],
    examples: ['The reception team welcomes new employees. → team là chủ ngữ; welcomes là động từ; employees là tân ngữ.', 'Please complete the registration form carefully. → registration bổ nghĩa cho form; carefully mô tả complete.', 'Our new coordinator is helpful. → helpful đứng sau is, mô tả coordinator.'],
    vocabulary: ['reception — quầy lễ tân', 'colleague — đồng nghiệp', 'department — phòng ban', 'orientation — buổi hướng dẫn nhập môn', 'extension — số máy lẻ', 'badge — thẻ nhân viên', 'supervisor — người giám sát', 'directory — danh bạ'],
    passageTitle: 'Welcome to Maple Office',
    reading: 'Welcome to Maple Office. New employees should arrive at reception at 8:45 on Monday. Please bring photo identification so that the receptionist can issue a visitor badge. The orientation begins in Room 204 at 9:00 and finishes at 10:30. During the session, Ms. Lan from Human Resources will explain leave requests and introduce the department supervisors. Computer accounts will be ready after lunch. If your account does not work, call the IT desk on extension 315. Parking spaces beside the main entrance are reserved for visitors; staff should use the north car park. A short office tour follows the orientation. You do not need to bring a laptop to the morning session.',
    script: 'Welcome to your first day at Maple Office. My name is Anna, and I work at reception. The orientation is in Room two hundred and four, on the second floor. Please collect your badge before you go upstairs. Your supervisor will meet you after the office tour. Lunch is available in the staff kitchen from twelve thirty. If you need help with your computer account, call the IT desk on extension three one five. We are glad to have you on the team.',
    listening: [q('What should employees collect before going upstairs?', ['A computer','A badge','A parking ticket'],1,'“Collect your badge before you go upstairs” nêu trực tiếp thứ cần lấy.'),q('Who meets new employees after the tour?', ['Their supervisor','A visitor','The delivery driver'],0,'Người gặp sau chuyến tham quan là supervisor; không phải receptionist đang nói.')],
    speaking: 'Bạn là nhân viên mới. Giới thiệu tên, phòng ban, hai nhiệm vụ và một điều muốn hỏi trong 45–60 giây. Dùng ít nhất ba câu có động từ khác nhau. Tự nghe lại và kiểm tra từng câu có chủ ngữ, động từ.',
    assignment: 'Viết email 80–100 từ cho người hướng dẫn: giới thiệu phòng ban, nêu hai nhiệm vụ dự kiến và hỏi nơi nhận tài khoản máy tính. Có tiêu đề, lời chào và lời kết. Nộp văn bản trực tiếp hoặc tệp PDF/TXT; không đưa mật khẩu hay thông tin cá nhân nhạy cảm vào bài.',
    model: 'Subject: First-day introduction\nDear Ms. Lan,\nMy name is Mai, and I am joining the customer service department. I will answer customer emails and update the appointment list. I am pleased to meet the team and learn our working procedures. Could you please tell me where I can collect my computer account details? I will attend the orientation on Monday morning and bring my identification. Thank you for your guidance.\nKind regards,\nMai',
    quiz: [q('The new assistant is very _____.',['help','helpful','helpfully','helpfulness'],1,'Sau is very cần tính từ: helpful. Helpfully là trạng từ, helpfulness là danh từ.'),q('Please complete the form _____.',['careful','care','carefully','caring'],2,'Cần trạng từ bổ nghĩa cho complete: carefully.'),q('Who explains leave requests?',['The IT desk','Ms. Lan','A visitor','The receptionist'],1,'Thông báo giao phần này cho Ms. Lan from Human Resources.'),q('When are computer accounts ready?',['Before 8:45','At 9:00','After lunch','Next week'],2,'“Computer accounts will be ready after lunch.”'),q('Where should staff park?',['Beside reception','At the north car park','At Room 204','By the visitor entrance'],1,'Chỗ gần cửa chính dành cho khách; nhân viên dùng north car park.'),q('What must new employees bring?',['A laptop','A parking permit','Photo identification','Lunch vouchers'],2,'Cần giấy tờ có ảnh để nhận thẻ; thông báo nói không cần laptop.'),q('Our _____ begins at nine.',['orient','orientation','oriented','orienting'],1,'Sau tính từ sở hữu Our cần danh từ làm chủ ngữ: orientation.'),q('Which is a complete sentence?',['The staff in the lobby.','The new office directory.','Our supervisor checks the list.','Before the morning tour.'],2,'Chỉ câu này có chủ ngữ Our supervisor và động từ checks.')],
  },
  {
    title: 'Thói quen và giờ làm việc', grammar: 'Hiện tại đơn và trạng từ tần suất',
    goals: ['Chia đúng hiện tại đơn với chủ ngữ số ít và số nhiều.', 'Phân biệt giờ mở cửa với lịch làm việc cá nhân.', 'Mô tả lịch một ngày và hỏi giờ làm.'],
    notes: ['Hiện tại đơn diễn tả thói quen: We open at eight. Chủ ngữ he/she/it hoặc danh từ số ít thường thêm -s/-es: The branch closes at six.', 'Phủ định dùng do not/does not + động từ nguyên mẫu: The manager does not work on Sundays. Không thêm s vào work sau does.', 'Câu hỏi dùng Do/Does + chủ ngữ + động từ: Does the office open early? Wh-question đặt từ hỏi trước trợ động từ: When does it close?', 'Usually/often đứng trước động từ thường nhưng sau be: She usually arrives early. She is usually available. Every Monday là lịch lặp lại, không phải một buổi đã thực sự diễn ra.'],
    examples: ['The finance team reviews invoices every Friday.', 'Our supervisor does not hold meetings during lunch.', 'What time does the support desk close?'],
    vocabulary: ['shift — ca làm', 'weekday — ngày trong tuần', 'available — có thể tiếp nhận', 'break — giờ nghỉ', 'opening hours — giờ mở cửa', 'roster — bảng phân ca', 'regularly — thường xuyên', 'overtime — thời gian làm thêm'],
    passageTitle: 'Revised customer desk hours',
    reading: 'From next month, the Cedar customer desk opens at 8:30 from Monday to Friday. It closes at 17:30, except on Wednesdays, when it remains open until 19:00. Customers can visit without an appointment for general enquiries. Product demonstrations require a booking because a specialist must prepare the equipment. Staff take lunch in two groups, so the desk remains open throughout the day. On Saturdays, the desk operates from 9:00 to 12:00 with a smaller team. Telephone support is not available on Sundays, but customers can leave an online message. The desk supervisor checks those messages on Monday morning and assigns them to the appropriate team member.',
    script: 'Good afternoon. This is the Cedar customer desk. We open at eight thirty on weekdays. On Wednesdays, our team stays until seven in the evening. If you want a product demonstration, please book a time with our specialist. You do not need an appointment for a general question. Our Saturday service ends at noon. For Sunday enquiries, please use the online message form. A team member will contact you on Monday.',
    listening: [q('On which day does the desk stay open later?',['Monday','Wednesday','Saturday'],1,'Wednesday được nêu cùng giờ đóng cửa 7 p.m.'),q('What requires a booking?',['A general question','Leaving a message','A product demonstration'],2,'Cần chuyên viên chuẩn bị thiết bị cho demonstration.')],
    speaking: 'Nói về một ngày học hoặc làm việc điển hình trong 60 giây: giờ bắt đầu, ba việc thường làm và một việc không làm cuối tuần. Dùng usually, sometimes, never đúng vị trí.',
    assignment: 'Viết 90–110 từ mô tả lịch hỗ trợ của một nhóm tự chọn. Phân biệt lịch ngày thường, một ngày làm muộn và cuối tuần. Viết thêm ba câu hỏi khách hàng có thể hỏi, kèm câu trả lời. Không khẳng định đó là giờ làm thực tế của Smart English.',
    model: 'Our help desk usually opens at nine on weekdays and closes at five. On Thursdays, it stays open until six for customers who work late. Two assistants answer general questions, and a specialist handles technical requests. The desk does not open on Sundays. Customers can send an email at any time, but staff check the inbox during working hours.\nWhat time does the desk open? — It opens at nine.\nDoes it open on Sundays? — No, it does not.\nWho handles technical requests? — A specialist does.',
    quiz: [q('The desk _____ at 8:30.',['open','opening','opens','to open'],2,'The desk là chủ ngữ số ít nên dùng opens.'),q('The supervisor does not _____ on Sundays.',['works','work','working','worked'],1,'Sau does not dùng nguyên mẫu work.'),q('What happens on Wednesdays?',['The desk closes at noon.','Only messages are accepted.','The desk closes later.','Demonstrations are cancelled.'],2,'Thứ Tư đóng lúc 19:00, muộn hơn ngày thường 17:30.'),q('Why do demonstrations require a booking?',['To reserve parking','To prepare equipment','To arrange lunch','To print invoices'],1,'Chuyên viên cần chuẩn bị thiết bị.'),q('Who checks Sunday messages?',['The supervisor','The customer','A Saturday visitor','The equipment supplier'],0,'Desk supervisor kiểm tra vào sáng thứ Hai.'),q('When does Saturday service end?',['At 8:30','At noon','At 17:30','At 19:00'],1,'Saturday operates from 9:00 to 12:00.'),q('She _____ arrives before nine.',['usually','is usually','usual','does usually to'],0,'Trạng từ tần suất đứng trước động từ arrives, không thêm is.'),q('_____ the specialist work on Saturdays?',['Do','Is','Does','Has'],2,'Câu hỏi hiện tại đơn với specialist số ít dùng Does.')],
  },
  {
    title: 'Sắp xếp cuộc họp', grammar: 'Giới từ thời gian và hiện tại tiếp diễn',
    goals: ['Dùng at/on/in với giờ, ngày và tháng.', 'Đọc thư đổi lịch và phân biệt thời gian cũ với thời gian mới.', 'Đề nghị một khung giờ thay thế lịch sự.'],
    notes: ['At dùng với giờ: at 10:15. On dùng với ngày: on Tuesday, on 24 November. In dùng với tháng/năm: in December, in 2027.', 'Hiện tại tiếp diễn dùng be + V-ing: We are discussing the budget. Nó cũng diễn tả sắp xếp tương lai đã định: We are meeting the supplier on Tuesday.', 'Không nhầm thời điểm diễn ra với hạn thực hiện: by Friday nghĩa là chậm nhất thứ Sáu; until Friday nói trạng thái kéo dài đến thứ Sáu.', 'Khi thư có rescheduled/moved, gạch dưới thời gian mới. Thời gian cũ thường xuất hiện làm phương án nhiễu.'],
    examples: ['The briefing starts at ten on Tuesday.', 'We are meeting in the training room next week.', 'Please confirm your attendance by Friday.'],
    vocabulary: ['agenda — chương trình họp', 'reschedule — đổi lịch', 'confirm — xác nhận', 'attend — tham dự', 'venue — địa điểm', 'attachment — tệp đính kèm', 'briefing — buổi phổ biến thông tin', 'minutes — biên bản họp'],
    passageTitle: 'Supplier meeting: new time and room',
    reading: 'Dear colleagues, the supplier briefing originally planned for Tuesday at 10:00 has moved to Thursday at 14:00. Our supplier cannot arrive on Tuesday because its product team is attending a trade event. We will meet in Training Room B, not the boardroom, which is undergoing maintenance. Please read the attached product summary before the meeting. The first thirty minutes will cover delivery options, followed by a short demonstration. Send any questions to An by Wednesday at 16:00 so that the supplier can prepare clear answers. Colleagues who cannot attend should nominate a team representative. An will circulate the meeting minutes on Friday morning.',
    script: 'Hello, this is An with a change to the supplier briefing. We are meeting on Thursday at two, in Training Room B. The boardroom is not available because of maintenance. Please read the product summary first. If you have questions, send them to me by four on Wednesday. You can ask a colleague to attend for your team if you are unavailable. I will send the minutes on Friday morning.',
    listening: [q('Where will the briefing take place?',['The boardroom','Training Room B','A trade event'],1,'Training Room B thay cho boardroom đang bảo trì.'),q('When should questions reach An?',['Wednesday by four','Thursday after two','Friday morning'],0,'By four on Wednesday là hạn gửi câu hỏi, không phải giờ họp.')],
    speaking: 'Đóng vai gọi điện đổi lịch họp: nêu giờ cũ, lý do, hai lựa chọn mới và đề nghị xác nhận. Ghi âm tự luyện 45–60 giây; chưa nộp bản ghi nếu hệ thống chưa hỗ trợ định dạng.',
    assignment: 'Viết email 100–120 từ đề nghị đổi buổi trao đổi từ 09:00 thứ Ba sang 14:00 thứ Năm. Nêu lý do trung tính, địa điểm mới, tài liệu cần đọc và hạn xác nhận vào 16:00 thứ Tư. Các ngày trong đề là tình huống ngôn ngữ, hạn nộp thật xem trên hoạt động.',
    model: 'Subject: Request to reschedule our briefing\nDear colleagues,\nCould we move our Tuesday briefing from 9:00 to 14:00 on Thursday? Our product specialist has a prior appointment on Tuesday. Training Room B is available on Thursday and has the equipment we need. Please read the product summary before we meet and send me any questions in advance. Could you confirm your attendance by 16:00 on Wednesday? If you cannot join us, please nominate a colleague to represent your team. I will share the minutes after the meeting. Thank you for your flexibility.\nBest regards,\nAn',
    quiz: [q('The meeting begins _____ 14:00.',['in','on','at','by the'],2,'Giờ cụ thể dùng at.'),q('We are _____ the supplier on Thursday.',['meet','meeting','meets','met'],1,'Hiện tại tiếp diễn: are meeting.'),q('What is the new meeting day?',['Tuesday','Wednesday','Thursday','Friday'],2,'Thư đổi từ Tuesday sang Thursday.'),q('Why is the boardroom unavailable?',['A demonstration is there.','It is being maintained.','The supplier booked it.','It has no chairs.'],1,'Boardroom is undergoing maintenance.'),q('What should participants read first?',['The minutes','A travel policy','The product summary','A maintenance log'],2,'Tài liệu đính kèm là product summary.'),q('Who may attend instead of an unavailable colleague?',['A team representative','A maintenance worker','Any customer','A driver'],0,'Người vắng có thể nominate a team representative.'),q('Submit your questions _____ Wednesday at 16:00.',['until','by','during','since'],1,'By chỉ hạn chót hoàn thành việc gửi câu hỏi.'),q('The team is meeting _____ December.',['on','at','in','to'],2,'Tháng dùng giới từ in.')],
  },
  {
    title: 'Tuyển dụng và kinh nghiệm', grammar: 'Quá khứ đơn và trình tự sự kiện',
    goals: ['Phân biệt quá khứ đơn khẳng định và phủ định.', 'Đọc yêu cầu tuyển dụng, nhiệm vụ và hồ sơ ứng tuyển.', 'Mô tả một trải nghiệm bằng dữ kiện rõ ràng.'],
    notes: ['Quá khứ đơn diễn tả việc đã kết thúc ở mốc quá khứ: She joined the team in 2024. Động từ thường thêm -ed; động từ bất quy tắc cần học theo cụm: send–sent, write–wrote.', 'Phủ định dùng did not + nguyên mẫu: He did not send the file. Câu hỏi: When did she apply? Không dùng did applied.', 'Was/were là quá khứ của be: The interview was online. The candidates were ready. Với be không dùng trợ động từ did.', 'Từ nối first, then, after that, finally giúp kể trình tự. Trong CV không bịa bằng cấp hay kinh nghiệm; bài tập có thể mô tả một dự án học tập có thật.'],
    examples: ['I assisted the reception team last summer.', 'We did not receive the application yesterday.', 'After the interview, the recruiter sent a short email.'],
    vocabulary: ['vacancy — vị trí đang tuyển', 'applicant — người ứng tuyển', 'qualification — điều kiện chuyên môn', 'experience — kinh nghiệm', 'reference — người tham chiếu', 'deadline — hạn chót', 'interview — phỏng vấn', 'temporary — tạm thời'],
    passageTitle: 'Part-time service assistant',
    reading: 'Harbor Services is recruiting a part-time service assistant for its information centre. The assistant will answer enquiries, update visitor records and prepare weekly summaries. Applicants should communicate clearly in English and use basic spreadsheet functions. Previous customer service experience is helpful but not essential; training is provided. The role requires three weekday afternoons each week. Send a short CV and a paragraph explaining your interest to the recruitment team by 30 November. Interviews will take place online during the first week of December. Shortlisted applicants will receive an invitation by email. Please do not visit the information centre to submit a paper application because recruitment is handled by a separate team.',
    script: 'Thank you for your interest in the service assistant role. We received your application on Monday. Your online interview is scheduled for next Wednesday at three in the afternoon. It will last about twenty minutes. Please prepare an example of a time you helped someone solve a problem. You do not need to bring printed documents. If the interview time is unsuitable, reply to this message and suggest another weekday afternoon.',
    listening: [q('How long will the interview last?',['Ten minutes','Twenty minutes','An hour'],1,'“About twenty minutes” là thời lượng được nêu.'),q('What should the applicant prepare?',['Printed documents','A sales report','An example of helping someone'],2,'Người ứng tuyển cần một ví dụ giải quyết vấn đề, không phải bản in.')],
    speaking: 'Kể về một lần bạn giúp bạn học hoặc đồng nghiệp trong 60 giây. Nêu tình huống, hành động và điều học được. Chỉ dùng trải nghiệm có thật; có thể nói rõ đây là bài nhập vai nếu chọn tình huống giả định.',
    assignment: 'Viết đoạn giới thiệu 100–120 từ cho vị trí trợ lý thông tin. Nêu hai kỹ năng, một dự án học tập có thật hoặc tình huống nhập vai được ghi rõ, và lịch có thể làm việc. Không tự thêm bằng cấp hoặc chứng chỉ vào bài. Kiểm tra ít nhất bốn động từ quá khứ.',
    model: 'I am interested in the information centre role because I enjoy helping people find clear answers. During a university group project, I organised our contact list and prepared a short weekly summary. I also helped two classmates check their spreadsheet formulas. These tasks taught me to explain information patiently and keep records accurate. I can communicate in English about everyday office tasks, and I am willing to complete the training. I am available on three weekday afternoons. I would welcome the opportunity to discuss how my skills could support your team.',
    quiz: [q('The recruiter _____ an email yesterday.',['send','sends','sent','sending'],2,'Yesterday yêu cầu quá khứ đơn; send có dạng quá khứ sent.'),q('She did not _____ the paper application.',['submitted','submit','submits','submitting'],1,'Sau did not dùng nguyên mẫu submit.'),q('Which skill is required?',['Advanced programming','Basic spreadsheet use','Driving a bus','Legal translation'],1,'Thông báo yêu cầu basic spreadsheet functions.'),q('Is previous service experience essential?',['Yes, five years are needed.','No, training is provided.','Only for online interviews.','It is not mentioned.'],1,'Helpful but not essential; công ty có đào tạo.'),q('How should candidates apply?',['Bring a paper form','Call the information desk','Send a CV and a paragraph','Visit a training room'],2,'Ứng viên gửi short CV và đoạn nêu lý do quan tâm.'),q('Where are interviews held?',['At the centre','At a college','Online','At a trade fair'],2,'Interviews take place online.'),q('The candidates _____ ready for the interview.',['was','were','did','be'],1,'Candidates số nhiều dùng were.'),q('When _____ you apply?',['did','were','was','does'],0,'Câu hỏi quá khứ với apply dùng did.')],
  },
  {
    title: 'Đơn hàng và số lượng', grammar: 'Danh từ đếm được và lượng từ',
    goals: ['Dùng many/much, a few/a little và some/any.', 'Đối chiếu số lượng đặt, số lượng giao và số lượng thiếu.', 'Viết yêu cầu bổ sung hàng với số liệu nhất quán.'],
    notes: ['Danh từ đếm được có số nhiều: chairs, boxes. Danh từ không đếm được như equipment, information không thêm -s trong nghĩa thông thường.', 'Many đi với danh từ đếm được số nhiều; much với danh từ không đếm được. A few chairs, a little time đều diễn đạt có một lượng nhỏ.', 'Some thường dùng trong câu khẳng định và lời mời; any thường dùng trong câu hỏi hoặc phủ định: Do we have any envelopes?', 'Khi đọc đơn hàng, ghi riêng ordered, delivered và outstanding. Không coi số tiền hay số lượng trong bài luyện là một giao dịch thật của hệ thống.'],
    examples: ['We need a few replacement chairs.', 'The supplier gave us some useful information.', 'There is not much space in the storage room.'],
    vocabulary: ['purchase order — đơn đặt mua', 'quantity — số lượng', 'item — mặt hàng', 'stock — hàng tồn', 'replacement — hàng thay thế', 'delivery note — phiếu giao hàng', 'outstanding — còn thiếu/chưa xử lý', 'damaged — bị hỏng'],
    passageTitle: 'Delivery check for order 482',
    reading: 'To: Northline Supplies. We received the delivery for purchase order 482 this morning. The order listed twelve desk lamps, twenty storage boxes and six office chairs. All twelve lamps arrived in good condition. However, only eighteen boxes were included, and one of the six chairs has a broken armrest. Please send the two outstanding boxes and replace the damaged chair. Our reception team can accept deliveries between 9:00 and 16:00 on weekdays. Please call before arrival because large packages must enter through the side gate. We have attached photographs of the damaged item and a copy of the delivery note. Kindly confirm the replacement schedule by tomorrow afternoon.',
    script: 'Hello, this is Northline Supplies calling about order four eight two. Thank you for the photographs. We will send two storage boxes and one replacement chair on Thursday morning. The driver expects to arrive between ten and eleven. Please keep the damaged chair near the side gate so that the driver can collect it. There is no additional delivery charge for this replacement. Please call us if the morning delivery window is unsuitable.',
    listening: [q('What will the driver collect?',['Twelve lamps','The damaged chair','Twenty boxes'],1,'Người nói yêu cầu để damaged chair ở cổng phụ để thu hồi.'),q('When is the replacement expected?',['Thursday morning','Tomorrow evening','Saturday afternoon'],0,'Audio nói Thursday morning, khoảng10–11 giờ.')],
    speaking: 'Gọi điện báo thiếu hàng trong 60 giây: nói mã đơn, hai số lượng cần đối chiếu, mô tả lỗi và đề nghị xác nhận lịch. Đọc rõ số 12, 20, 18 và 2.',
    assignment: 'Viết email 100–130 từ dựa vào đơn 482: tóm tắt hàng đã nhận, xác định hai thùng còn thiếu và một ghế cần đổi, đề nghị lịch giao và nêu cổng nhận hàng. Có một câu dùng some/any và một câu dùng số lượng chính xác. Nộp văn bản; đây là bài thực hành, không gửi email cho nhà cung cấp.',
    model: 'Subject: Missing boxes and chair replacement — order 482\nDear Northline team,\nThank you for the delivery this morning. We received all twelve desk lamps, but only eighteen of the twenty storage boxes arrived. In addition, one chair has a broken armrest. Could you please send the two missing boxes and arrange a replacement chair? We have attached some photographs and the delivery note for your reference. Our reception team accepts deliveries from 9:00 to 16:00 on weekdays. Please use the side gate and call before arriving. Could you confirm the proposed delivery window by tomorrow afternoon?\nKind regards,\nMai',
    quiz: [q('We need _____ information about delivery.',['many','a few','some','an'],2,'Information không đếm được nên some phù hợp.'),q('There are only _____ boxes left.',['a little','much','a few','an'],2,'Boxes đếm được số nhiều, dùng a few.'),q('How many boxes are missing?',['One','Two','Six','Twelve'],1,'Đặt20nhận18, thiếu2thùng.'),q('Which item is damaged?',['A desk lamp','A storage box','An office chair','The side gate'],2,'Một ghế có broken armrest.'),q('Where should large packages enter?',['The main lobby','The side gate','The staff kitchen','The north car park'],1,'Gói lớn đi qua side gate.'),q('What accompanies the request?',['A bank receipt','Photographs and a delivery note','A new job application','A room booking'],1,'Thư đính kèm ảnh và copy delivery note.'),q('Do you have _____ replacement parts?',['any','much','a','little'],0,'Câu hỏi với danh từ số nhiều parts dùng any.'),q('Choose the standard expression.',['Many equipments','Some equipment','An equipment','Three informations'],1,'Equipment không đếm được; some equipment là cách dùng chuẩn.')],
  },
  {
    title: 'Hỗ trợ khách hàng', grammar: 'Động từ khuyết thiếu và lời yêu cầu',
    goals: ['Dùng can/could/should/must đúng với động từ nguyên mẫu.', 'Phân biệt đề nghị, khuyến nghị và yêu cầu bắt buộc.', 'Trả lời khiếu nại bằng thông tin cụ thể, lịch sự.'],
    notes: ['Can/could/may/must/should theo sau bằng động từ nguyên mẫu: Could you send the receipt? Không dùng could to send.', 'Could you…? lịch sự khi yêu cầu. Would you like…? là lời mời. Should diễn đạt lời khuyên; must diễn đạt yêu cầu mạnh.', 'Must not là không được phép. Do not have to nghĩa là không bắt buộc, khác nghĩa với must not.', 'Thư hỗ trợ tốt xác nhận vấn đề, nêu bước xử lý và thời điểm phản hồi. Không hứa hoàn tiền hoặc kết quả ngoài quyền hạn.'],
    examples: ['Could you describe the problem in one sentence?', 'You should keep a copy of the order confirmation.', 'Customers do not have to print the form.'],
    vocabulary: ['enquiry — câu hỏi/yêu cầu thông tin', 'complaint — khiếu nại', 'resolve — giải quyết', 'refund — hoàn tiền', 'receipt — biên nhận', 'warranty — bảo hành', 'request — yêu cầu', 'response — phản hồi'],
    passageTitle: 'A delayed replacement request',
    reading: 'Dear Ms. Park, thank you for contacting us about your replacement headset. We understand that the delay has affected your online meetings. The warehouse has confirmed that the replacement is ready for dispatch. To complete the request, could you reply with your current delivery address and the order reference? Please do not send your payment card details. We expect the courier to collect the parcel within two working days, and we will email a tracking link after collection. You do not have to return the original headset until the replacement arrives. If your address has changed since the order, please tell us before dispatch. We appreciate your patience and will update you if the collection schedule changes.',
    script: 'Thank you for calling customer support. I can help you check the replacement request. Could you give me the order reference, please? You should not share your payment card number. The parcel is ready, and the courier is expected within two working days. We will send a tracking link after collection. You do not have to return the original headset today. Please wait until the replacement arrives.',
    listening: [q('What information does support request?',['A card number','An order reference','A bank password'],1,'Order reference dùng để tra cứu; cardnumber được nhắc là không cung cấp.'),q('When should the original headset be returned?',['Before calling','Today','After the replacement arrives'],2,'Do not have to return today; đợi replacement đến.')],
    speaking: 'Đóng vai nhân viên hỗ trợ trong 60 giây: ghi nhận vấn đề, hỏi thông tin đơn hàng không nhạy cảm, nêu hai bước tiếp theo. Dùng Could you…? và You should…; không cam kết khoản hoàn tiền.',
    assignment: 'Viết phản hồi 110–130 từ cho khách bị chậm tai nghe thay thế. Hỏi địa chỉ và mã đơn, nêu thời gian dự kiến trong hai ngày làm việc, giải thích khi nào có tracking và khi nào trả món cũ. Thêm lời nhắc không chia sẻ thông tin thẻ. Không ghi nhận thanh toán hoặc hoàn tiền thật.',
    model: 'Dear Ms. Park,\nThank you for letting us know about the delay. I understand that you need the headset for online meetings. The replacement is ready for dispatch. Could you please confirm your current delivery address and order reference? Please do not include your payment card details. We expect the courier to collect the parcel within two working days. You will receive a tracking link after collection, so you can follow its progress. You do not have to return the original headset before the replacement arrives. We will contact you if the collection schedule changes. Thank you for your patience.\nKind regards,\nCustomer Support',
    quiz: [q('Could you _____ your order reference?',['to send','sending','send','sent'],2,'Sau could dùng động từ nguyên mẫu send.'),q('You do not have to print the form means:',['Printing is forbidden.','Printing is optional.','Printing is required.','The form is missing.'],1,'Do not have to chỉ không bắt buộc; không có nghĩa cấm.'),q('What caused the customer concern?',['A delayed replacement','A wrong interview date','A missing room','A salary change'],0,'Khách chờ replacement headset và bị ảnh hưởng họp online.'),q('What must the customer avoid sending?',['The order reference','A delivery address','Payment card details','A support question'],2,'Thư dặn không gửi payment card details.'),q('When will tracking be sent?',['Before the request','After courier collection','At the original purchase','Only after return'],1,'Email tracking sau khi courier lấy bưu kiện.'),q('What should a changed address be reported before?',['The next year','Dispatch','The first meeting','The return deadline'],1,'Báo thay đổi trước dispatch để giao đúng nơi.'),q('You _____ keep a copy for reference.',['should','should to','shoulds','are should'],0,'Modal should theo sau bằng keep nguyên mẫu.'),q('You must not share a password means:',['Sharing is optional.','Sharing is required.','Sharing is not allowed.','The password has expired.'],2,'Must not diễn đạt cấm, không phải không bắt buộc.')],
  },
  {
    title: 'Đi công tác và đặt chỗ', grammar: 'Tương lai và điều kiện loại một',
    goals: ['Dùng will cho thông báo và if + hiện tại cho điều kiện tương lai.', 'Đọc hành trình và xác định giới hạn dịch vụ.', 'Xác nhận đặt chỗ và yêu cầu thay đổi rõ ràng.'],
    notes: ['Will + nguyên mẫu thường dùng cho thông báo, quyết định hoặc dự đoán: The driver will wait outside.', 'Điều kiện loại một: If + hiện tại đơn, will + nguyên mẫu. If the flight is delayed, we will contact the hotel. Không đặt will trong mệnh đề if của dạng cơ bản này.', 'Be going to + động từ diễn tả kế hoạch: We are going to visit the client. Hiện tại tiếp diễn có thể diễn đạt lịch hẹn đã thu xếp.', 'Trong lịch trình, phân biệt departure với arrival, check-in với check-out. Đọc đơn vị giờ và điều kiện thay đổi, không suy ra dịch vụ không được nêu.'],
    examples: ['If the train arrives late, I will call the driver.', 'We are going to meet the client after lunch.', 'The hotel will hold the room until midnight.'],
    vocabulary: ['itinerary — hành trình', 'departure — khởi hành', 'arrival — đến nơi', 'reservation — đặt chỗ', 'check-in — nhận phòng', 'shuttle — xe đưa đón', 'delay — chậm trễ', 'confirmation — xác nhận'],
    passageTitle: 'Travel arrangements for the client visit',
    reading: 'Your train to River City departs at 7:20 on Monday and arrives at 9:05. A hotel shuttle will meet guests outside Exit C at 9:30. Please show the driver your reservation confirmation. The hotel room will be available from 14:00; bags can be stored at reception before that time. The client meeting begins at 11:00 in the nearby business centre, a ten-minute walk from the hotel. If the train is delayed by more than twenty minutes, call the hotel so that staff can advise you about the next shuttle. Breakfast is included in the room rate, but evening meals are not. Check-out is at 11:00 on Wednesday. Please review the attached itinerary before departure.',
    script: 'This is a reminder about Monday travel. Your train arrives at nine oh five. The hotel shuttle leaves from Exit C at nine thirty. Please have your reservation confirmation ready. You can leave your bags at reception, but room check-in starts at two in the afternoon. If your train is more than twenty minutes late, call the hotel for the next shuttle time. The client meeting starts at eleven, in the business centre near the hotel.',
    listening: [q('Where does the shuttle meet guests?',['Exit C','The client office','The train platform'],0,'Audio nêu Exit C cho điểm đón shuttle.'),q('What can travellers do before check-in?',['Enter the room immediately','Store bags at reception','Have an included evening meal'],1,'Được gửi hành lý; phòng chỉ sẵn từ14:00.')],
    speaking: 'Xác nhận hành trình 60 giây: giờ đến, điểm đón, thời gian nhận phòng và cách xử lý nếu trễ tàu. Dùng ít nhất một câu If…, we will… đúng cấu trúc.',
    assignment: 'Viết email 100–130 từ xác nhận đặt phòng và hỏi chuyến shuttle tiếp theo nếu tàu trễ 30 phút. Nêu giờ đến gốc, điểm đón, nhu cầu gửi hành lý và giờ họp. Đây là bài nhập vai; không gửi đặt phòng thật.',
    model: 'Dear Reception Team,\nI am writing to confirm my reservation for the client visit. My train is scheduled to arrive at 9:05 on Monday, and I plan to take the 9:30 shuttle from Exit C. If the train is thirty minutes late, could you please advise me about the next available shuttle? I understand that check-in begins at 14:00. I would like to leave my bags at reception before attending an 11:00 meeting at the nearby business centre. I will bring my reservation confirmation for the driver. Thank you for your assistance.\nBest regards,\nMai',
    quiz: [q('If the train _____ late, we will call.',['will arrive','arrives','arriving','arrive to'],1,'Mệnh đề if dùng hiện tại đơn arrives.'),q('The driver will _____ outside.',['waits','waiting','wait','to wait'],2,'Sau will dùng wait nguyên mẫu.'),q('When does the train arrive?',['7:20','9:05','9:30','14:00'],1,'7:20làgiờđi;9:05làgiờđến.'),q('What must guests show the driver?',['A CV','A reservation confirmation','A parking ticket','A meal receipt'],1,'Cần reservation confirmation.'),q('Which meal is included?',['Lunch','All meals','Breakfast','Dinner'],2,'Breakfast included, evening meals not included.'),q('When should travellers call the hotel?',['For a delay over twenty minutes','Only after midnight','Before any train departs','Whenever bags are stored'],0,'Điều kiện gọi là train delayed more than20minutes.'),q('Check-out is _____ Wednesday at eleven.',['in','on','at','by the'],1,'Ngày trong tuần dùng on.'),q('They are going to _____ the client.',['visit','visits','visited','visiting'],0,'Be going to đi với động từ nguyên mẫu visit.')],
  },
  {
    title: 'Bảo trì và hướng dẫn an toàn', grammar: 'Câu bị động và mệnh lệnh',
    goals: ['Nhận diện bị động hiện tại và quá khứ.', 'Đọc thông báo bảo trì, khu vực ảnh hưởng và hướng thay thế.', 'Trình bày một quy trình ngắn bằng động từ rõ ràng.'],
    notes: ['Bị động nhấn vào đối tượng chịu hành động: The lift is inspected every month. Cấu trúc be + quá khứ phân từ, không phải be + V-ing.', 'Quá khứ bị động dùng was/were + phân từ: The filters were replaced yesterday. Với will: The system will be checked tomorrow.', 'Câu mệnh lệnh bắt đầu bằng nguyên mẫu: Use the east stairs. Phủ định: Do not enter the work area.', 'Thời gian bảo trì dự kiến không đồng nghĩa đã hoàn thành. Đọc will/is scheduled to như kế hoạch; chỉ nói completed khi nguồn xác nhận.'],
    examples: ['The main entrance is cleaned every evening.', 'The damaged cable was replaced last week.', 'Keep the emergency exit clear.'],
    vocabulary: ['maintenance — bảo trì', 'inspection — kiểm tra', 'temporary — tạm thời', 'access — lối vào/quyền tiếp cận', 'equipment — thiết bị', 'emergency exit — lối thoát hiểm', 'technician — kỹ thuật viên', 'restore — khôi phục'],
    passageTitle: 'Lift inspection notice',
    reading: 'The east lift will be inspected on Saturday from 8:00 to 12:00 and will not be available during this period. Please use the west lift or the main stairs. Deliveries of large equipment should be rescheduled because the west lift is smaller. Contractors must sign in at the security desk and wear an identification badge. The inspection team will place barriers around the work area; staff must not move them. If work takes longer than expected, security will post an update at reception. Normal service is expected to resume after the safety check has been completed. Please keep both stairway doors clear at all times. Contact building services if you need assistance planning an accessible route.',
    script: 'Attention, please. The east lift is closed for an inspection on Saturday morning. You can use the west lift or the main stairs. Large equipment deliveries should be moved to another day. Contractors must sign in at security and keep their badges visible. Do not move the barriers around the work area. If you need an accessible route, please contact building services before your visit.',
    listening: [q('Which lift is being inspected?',['The west lift','The east lift','Both lifts'],1,'East lift đóng kiểm tra;westliftlàphươngánthaythế.'),q('What should happen to large equipment deliveries?',['Use the smaller lift','Be moved to another day','Arrive during inspection'],1,'Lời khuyên chuyển ngày vì westlift nhỏ hơn.')],
    speaking: 'Trình bày thông báo bảo trì 60 giây: nơi đóng, khoảng thời gian, lối thay thế và hai yêu cầu an toàn. Dùng một câu bị động và hai câu mệnh lệnh.',
    assignment: 'Viết thông báo 100–120 từ về việc kiểm tra thang máy phía đông 08:00–12:00 thứ Bảy. Nêu lối thay thế, ảnh hưởng giao hàng, cách liên hệ hỗ trợ và điều kiện khôi phục. Không nói việc kiểm tra đã hoàn thành; đây là lịch dự kiến của bài luyện.',
    model: 'The east lift will be inspected from 8:00 to 12:00 on Saturday. Please use the west lift or the main stairs during this period. As the west lift is smaller, large equipment deliveries should be arranged for another day. Contractors must sign in at the security desk and wear a visible badge. Do not move the barriers around the work area, and keep stairway doors clear. Security will post an update at reception if the inspection takes longer than expected. Normal service is expected after the safety check. Contact building services if you need help planning an accessible route.',
    quiz: [q('The lift _____ every month.',['inspects','is inspected','is inspecting','inspect'],1,'Lift chịu hành động: hiện tại bị động is inspected.'),q('The filters were _____ yesterday.',['replace','replacing','replaced','replaces'],2,'Bị động quá khứ: were +phântừreplaced.'),q('When is the east lift unavailable?',['Friday afternoon','Saturday morning','Sunday evening','Every weekday'],1,'Saturday08:00–12:00làbuổisáng.'),q('Why should large deliveries be moved?',['The west lift is smaller.','All stairs are closed.','Security has left.','The office is moving.'],0,'Westlift nhỏhơn, khóvậnchuyểnthiếtbịlớn.'),q('Where must contractors sign in?',['At the hotel','At the security desk','At the supplier office','On the train'],1,'Contractorssigninatsecuritydesk.'),q('What happens if work takes longer?',['Staff remove barriers.','Security posts an update.','The building closes forever.','Deliveries enter the work area.'],1,'Securitysẽpostupdateatreception.'),q('_____ the emergency exit clear.',['Keeps','Keeping','Keep','To keeping'],2,'MệnhlệnhdùngnguyênmẫuKeep.'),q('Which sentence describes a plan, not confirmed completion?',['The check was completed.','The lift was restored yesterday.','The lift will be inspected.','The technician signed the report.'],2,'Willbeinspectedchỉkếhoạchtươnglai.')],
  },
  {
    title: 'So sánh dịch vụ và lựa chọn', grammar: 'So sánh hơn và so sánh nhất',
    goals: ['Dùng đúng dạng so sánh tính từ.', 'So sánh hai đề xuất dựa trên nhiều tiêu chí.', 'Giải thích lựa chọn mà không bỏ qua điều kiện.'],
    notes: ['Tính từ ngắn thường thêm -er/-est: faster, fastest. Tính từ dài dùng more/most: more reliable. Sau so sánh hơn thường có than.', 'Một số dạng bất quy tắc: good–better–best; bad–worse–worst. Không dùng more better.', 'As…as diễn tả ngang bằng: The standard plan is as reliable as the premium plan. Less expensive nghĩa rẻ hơn.', 'Rẻ nhất không tự động phù hợp nhất. Trong đọc hiểu, kiểm tra dung lượng, thời gian hỗ trợ và điều kiện bổ sung trước khi quyết định.'],
    examples: ['Plan B is less expensive than Plan A.', 'The premium service offers a faster response.', 'This is the most flexible option for a small team.'],
    vocabulary: ['proposal — đề xuất', 'feature — tính năng', 'reliable — đáng tin cậy', 'flexible — linh hoạt', 'compare — so sánh', 'monthly fee — phí hàng tháng', 'limit — giới hạn', 'priority — ưu tiên'],
    passageTitle: 'Choosing a document service',
    reading: 'The office is comparing two document services. ClearFile costs 18 units per user each month and includes 100 gigabytes of storage. It offers support from 8:00 to 18:00 on weekdays. TeamArchive costs 24 units per user and provides 250 gigabytes, plus evening and weekend support. Both services allow secure document sharing and automatic backups. Our current team uses about 70 gigabytes per person, and most work takes place during weekday office hours. The project manager recommends starting with ClearFile for a three-month review period. If storage use grows, the team can reconsider the larger plan. Prices in this exercise are comparison units, not a bill or payment obligation.',
    script: 'We have compared the two document services. ClearFile is less expensive and already covers our current storage needs. TeamArchive provides more storage and longer support hours. Since our team mainly works on weekdays, the manager suggests trying ClearFile for three months. We will review actual storage use before extending the agreement. Both services have automatic backups, so that feature does not distinguish the two plans.',
    listening: [q('Why does the manager suggest ClearFile?',['It has the longest support hours.','It costs less and meets present needs.','It is the only secure service.'],1,'Giáthấphơnvàđủnhucầuhiệntạilàhaicăn cứ.'),q('Which feature do both services offer?',['Weekend support','250 gigabytes','Automatic backups'],2,'Automaticbackups cóởcảhai,khôngphảikhácbiệt.')],
    speaking: 'So sánh hai gói trong 60 giây. Nêu giá, dung lượng, giờ hỗ trợ và một điều kiện khiến bạn đổi lựa chọn. Dùng more, less và better chính xác.',
    assignment: 'Viết đề xuất 110–140 từ cho nhóm đang dùng 70GB/người. So sánh hai dịch vụ theo ba tiêu chí, chọn một gói cho ba tháng đầu và nêu khi nào cần xem lại. Dùng ít nhất ba cấu trúc so sánh; không ghi nhận hợp đồng hay thanh toán thật.',
    model: 'I recommend a three-month review of ClearFile for our current team. Its monthly fee is lower than TeamArchive, and its 100 gigabytes per user is enough for our present use of about 70 gigabytes. TeamArchive offers more storage and longer support hours, including weekends. However, most of our work takes place during weekday office hours, so the extra support is less important at this stage. Both services offer secure sharing and automatic backups. We should review storage use at the end of the trial period. If our documents grow significantly, the larger plan may become a better choice.',
    quiz: [q('This plan is _____ than the old one.',['cheap','cheaper','cheapest','more cheaper'],1,'So sánh hơn của cheap là cheaper.'),q('The new service is more _____ .',['reliably','reliability','reliable','rely'],2,'Sau more cần tính từ reliable.'),q('How much storage does ClearFile include?',['18 GB','70 GB','100 GB','250 GB'],2,'ClearFile100GB;70GBlànhucầudùnghiệntại.'),q('Which service provides weekend support?',['ClearFile only','TeamArchive only','Neither service','Both services'],1,'TeamArchive có eveningandweekendsupport.'),q('What is recommended initially?',['A three-month ClearFile review','A permanent larger plan','Stopping all backups','Buying both plans'],0,'Quảnlýđềnghị thử ClearFile trongba tháng.'),q('Which feature is shared?',['The monthly fee','Weekend support','Automatic backups','The storage limit'],2,'Cảhai đều có automaticbackups.'),q('Choose the correct comparison.',['More better','Gooder','Better','Most better'],2,'So sánh hơn bấtquytắc của good là better.'),q('The larger plan becomes relevant if _____.',['storage use grows','the team stops sharing','backups disappear','all staff leave'],0,'Bàiđọcnêuxemxétgóilớnhơnnếu storageusegrows.')],
  },
  {
    title: 'Tin nhắn và thông báo dài', grammar: 'Liên từ chỉ nguyên nhân và tương phản',
    goals: ['Phân biệt because, although, however và therefore.', 'Nghe mục đích, thay đổi và việc người nghe cần làm.', 'Tóm tắt thông báo không bỏ sót ngoại lệ.'],
    notes: ['Because nối mệnh đề chỉ nguyên nhân: We moved the event because the room is unavailable. Because of theo sau bằng danh từ/cụm danh từ: because of maintenance.', 'Although nối hai ý tương phản trong một câu: Although the room is smaller, it has enough seats. Không thêm but vào cùng cấu trúc although cơ bản.', 'However thường mở câu mới hoặc đi sau dấu chấm phẩy: The venue changed. However, the starting time is the same.', 'Therefore chỉ hệ quả. Khi nghe, ghi ba cột: vấn đề — thay đổi — hành động. Chú ý chi tiết giữ nguyên, không cho rằng mọi thứ đều đổi.'],
    examples: ['The entrance is closed because of repairs.', 'Although the venue changed, registration is still required.', 'The hall is unavailable; therefore, the workshop will move upstairs.'],
    vocabulary: ['announcement — thông báo', 'venue — địa điểm', 'registration — đăng ký', 'postpone — hoãn', 'remain — giữ nguyên', 'refreshments — đồ ăn/uống nhẹ', 'participant — người tham gia', 'noticeboard — bảng thông báo'],
    passageTitle: 'Workshop arrangements update',
    reading: 'The customer communication workshop will move from the ground-floor hall to Seminar Room 3 because repairs are taking place near the main entrance. Although the room has changed, the workshop will still begin at 9:30 on Friday. Participants should enter through the garden gate and follow the signs to the second floor. Registration opens at 9:00, and light refreshments will be available outside the room. Please bring your confirmation email; a printed copy is not necessary. The practical activity in the afternoon will use small groups, so participants should remain for the full programme. Anyone requiring step-free access should contact the organiser by Thursday noon so that an appropriate route can be arranged.',
    script: 'Good morning. We have an update about Friday workshop. Because of repairs near the main entrance, the workshop is moving to Seminar Room three. The starting time is still nine thirty. Please use the garden gate and follow the signs upstairs. Registration begins half an hour before the workshop. You can show your confirmation email on your phone. If you need step-free access, contact the organiser by noon on Thursday. We look forward to seeing you.',
    listening: [q('What remains unchanged?',['The room','The entrance','The workshop starting time'],2,'Stillninethirtynhấn mạnhgiờbắtđầugiữnguyên.'),q('What can participants show on a phone?',['Their confirmation email','A repair invoice','A room key'],0,'Khôngcầnbảnin;emailxácnhậntrênđiệnthoạiđượcchấpnhận.')],
    speaking: 'Tóm tắt thông báo trong 60 giây với ba phần: lý do thay đổi, điều thay đổi/giữ nguyên và việc cần làm. Dùng because of và although đúng cấu trúc.',
    assignment: 'Viết thông báo 110–130 từ cho người tham dự workshop: đổi phòng vì sửa chữa nhưng giữ giờ, chỉ lối vào mới, giờ đăng ký, loại xác nhận và cách xin hỗ trợ tiếp cận. Không tạo sự kiện workshop thật trong database; bài này là nội dung luyện viết.',
    model: 'Friday workshop will take place in Seminar Room 3 because of repairs near the main entrance. Although the venue has changed, the programme will still start at 9:30. Please use the garden gate and follow the signs to the second floor. Registration opens at 9:00, and light refreshments will be available outside the room. You can show your confirmation email on your phone; a printed copy is not required. Please remain for the afternoon group activity. If you need step-free access, contact the organiser by Thursday noon so that a suitable route can be arranged. Thank you for your cooperation.',
    quiz: [q('The venue changed _____ repairs.',['because','because of','although','however'],1,'Sau becauseof dùngdanhtừrepairs;becausecầnmệnhđề.'),q('_____ the room changed, the time stayed the same.',['Although','Because of','Therefore','During'],0,'Although nốiý tươngphản bằngmệnhđề.'),q('Where is the workshop now?',['Ground-floor hall','Seminar Room 3','The garden','At reception'],1,'Địachỉmớilà SeminarRoom3.'),q('When does registration open?',['8:30','9:00','9:30','12:00'],1,'Registrationopensat9:00;workshop9:30.'),q('Which entrance should participants use?',['Main entrance','The delivery gate','Garden gate','Staff car park'],2,'Sử dụng gardengate dosửachữa mainentrance.'),q('Who should contact the organiser early?',['People needing step-free access','Only group leaders','Everyone with a phone','Only late applicants'],0,'Hỗtrợstep-freecầnliênhệtrướchạn.'),q('The hall is closed. _____, we will use another room.',['However','Therefore','Although','Because of'],1,'Thereforenốihệquảphòngđóngnên dùngphòngkhác.'),q('A printed confirmation is _____.',['compulsory','not necessary','sent by security','available only Friday'],1,'Thôngbáonóiprintedcopyisnotnecessary.')],
  },
  {
    title: 'Đọc nhiều văn bản', grammar: 'Đại từ tham chiếu và mệnh đề quan hệ',
    goals: ['Theo dõi it/they/this và danh từ được thay thế.', 'Dùng who/which/that để bổ nghĩa.', 'Đối chiếu email, bảng lịch và tin nhắn để suy luận có căn cứ.'],
    notes: ['Who thường chỉ người; which chỉ vật; that có thể thay who/which trong nhiều mệnh đề xác định: The colleague who manages bookings is away.', 'Đại từ it thường thay một đối tượng số ít đã nêu, they thay số nhiều. Muốn xác định tham chiếu, đọc câu trước và kiểm tra nghĩa.', 'This/that có thể chỉ một ý hoặc thay đổi vừa nêu, không nhất thiết là danh từ gần nhất. Chọn phương án làm câu có nghĩa nhất.', 'Khi ghép văn bản, ghi ai viết, thời điểm và mục đích. Chỉ suy ra điều được cả hai nguồn hỗ trợ; không thêm thông tin từ kiến thức ngoài bài.'],
    examples: ['The room which has a projector is on the second floor.', 'The assistants who handle bookings work at reception.', 'The venue has changed. This affects the delivery route.'],
    vocabulary: ['reference — thông tin tham chiếu', 'attachment — tệp đính kèm', 'revised — đã điều chỉnh', 'capacity — sức chứa', 'equipment — thiết bị', 'requester — người yêu cầu', 'available — sẵn có', 'alternative — phương án thay thế'],
    passageTitle: 'Room request and coordinator reply',
    reading: 'Email 1 — From Linh to the booking team: We need a room for twelve people on Tuesday from 13:00 to 15:00. The session includes a product demonstration, so a projector and a reliable internet connection are essential. Room Oak was used last month, but its capacity is only ten. Please suggest an alternative.\nEmail 2 — From the coordinator to Linh: Room Pine, which seats sixteen, is available for your requested time. It has a projector, but the wireless connection is being upgraded. A wired connection is available at the front desk. Please tell us by Monday morning if your presenter needs an adapter. We will reserve Pine provisionally until then.\nMessage from Linh: Please keep Pine. Our presenter can use a wired connection and will bring her own adapter.',
    script: 'Hi Linh, this is the booking coordinator. Room Pine is available on Tuesday from one to three. It seats sixteen people, so there is enough space for your group. The wireless connection is being upgraded, but a wired connection is available. I received your message that the presenter will bring her own adapter. We will keep the room for you. Please collect the access card at reception before the session.',
    listening: [q('Why is Pine suitable for the group size?',['It seats sixteen.','It seats ten.','Only six people attend.'],0,'16chỗđápứngnhóm12;Oakchỉ10.'),q('What will the presenter bring?',['An access card','Her own adapter','A projector'],1,'Presenterbringownadapter;máychiếucósẵn.')],
    speaking: 'Báo cáo quyết định đặt phòng trong 60–75 giây. Nêu nhu cầu, hai lựa chọn, giới hạn internet và cách khắc phục. Dùng who hoặc which trong ít nhất một câu.',
    assignment: 'Viết email xác nhận 110–140 từ dựa vào ba văn bản: chọn Pine, nhắc 12 người/13:00–15:00, xác nhận mạng dây và adapter tự mang, hỏi nơi lấy thẻ. Tránh nhầm sức chứa16 với số người12. Bài nhập vai không thực hiện đặt phòng thật.',
    model: 'Dear Booking Team,\nPlease confirm Room Pine for our group of twelve on Tuesday from 13:00 to 15:00. The room, which seats sixteen, gives us enough space for the product demonstration. We understand that the wireless connection is being upgraded. Our presenter can use the wired connection and will bring her own adapter, so no additional adapter is required. Thank you for keeping the room provisionally while we checked these details. Could you please confirm where we should collect the access card and whether we need to return it immediately after the session? We appreciate your help.\nBest regards,\nLinh',
    quiz: [q('The colleague _____ manages bookings is away.',['which','who','where','when'],1,'Colleague chỉngười,dùng who.'),q('Pine has a projector. It also seats sixteen. What does It refer to?',['The presenter','The adapter','Room Pine','The coordinator'],2,'ItthayRoomPine,khôngphảiprojector vìđộngtừseats.'),q('Why is Oak unsuitable?',['It is too small.','It has no door.','It costs more.','It opens only at night.'],0,'Nhóm12nhưngOakchỉ10chỗ.'),q('Which time is requested?',['10:00–12:00','13:00–15:00','15:00–17:00','All Monday morning'],1,'Email1nêuthứBa13:00–15:00.'),q('What is the limitation at Pine?',['No projector','No chairs','Wireless is being upgraded','No wired connection'],2,'Wirelessđangnângcấp;cómạngdây.'),q('What can be inferred from the final message?',['Linh accepts the wired option.','The presenter needs a new adapter.','The meeting has been cancelled.','Oak has been enlarged.'],0,'Presenter dùngwiredvàtựmangadapter,nênLin hchấpnhậnPine.'),q('The room _____ has a projector is upstairs.',['who','which','when','whose the'],1,'Roomchỉvật,dùngwhich.'),q('How many participants are expected?',['Ten','Twelve','Sixteen','Twenty'],1,'12làsốngười;16làsứcchứaphòng.')],
  },
  {
    title: 'Tổng hợp và lập kế hoạch học tiếp', grammar: 'Hiện tại hoàn thành và ôn tập tích hợp',
    goals: ['Phân biệt kinh nghiệm đến hiện tại với sự việc tại mốc quá khứ.', 'Tổng hợp dữ kiện từ đoạn đọc và thông báo nghe.', 'Lập kế hoạch tiếp theo dựa trên tự đánh giá, không bịa điểm.'],
    notes: ['Hiện tại hoàn thành: have/has + quá khứ phân từ, nói kinh nghiệm hoặc việc liên quan hiện tại: We have updated the guide. Không gắn yesterday với cách dùng hiện tại hoàn thành cơ bản.', 'Quá khứ đơn dùng với thời điểm đã kết thúc: We updated it yesterday. So sánh I have attended three workshops với I attended one last Friday.', 'Already thường dùng với việc đã xong; yet thường trong câu hỏi hoặc phủ định: Have you checked the list yet? We have not received it yet.', 'Tự đánh giá nên dựa trên lỗi cụ thể: bỏ sót thời gian mới, nhầm danh từ/động từ, không đối chiếu số lượng. Chưa làm đánh giá thì không tự gán điểm hoặc năng lực đã đạt.'],
    examples: ['I have practised identifying new meeting times.', 'I reviewed the order email yesterday.', 'We have not confirmed the next workshop yet.'],
    vocabulary: ['review — ôn tập/xem xét', 'evidence — bằng chứng', 'strategy — chiến lược', 'accuracy — độ chính xác', 'fluency — độ trôi chảy', 'strength — điểm mạnh', 'priority — ưu tiên', 'next step — bước tiếp theo'],
    passageTitle: 'Learning review memo',
    reading: 'The learning team has prepared a review pack for participants in the workplace English programme. It contains short emails, service notices and meeting updates. Participants should complete one timed reading task and one listening task before the review meeting. They should keep a record of questions that were difficult and explain why they changed any answers. The review does not issue an official language certificate or guarantee a TOEIC score. Its purpose is to identify useful next steps. Participants who often miss dates should practise comparing original and revised schedules. Those who understand the message but struggle to reply should focus on short spoken summaries and structured emails. Please bring your error log and two examples of work you want feedback on.',
    script: 'As we prepare for the learning review, please complete one reading task and one listening task. Keep a short error log, including the reason for each difficult answer. Bring two examples of work that you would like feedback on. This review will help you plan your next steps. It does not provide an official language certificate. If you often miss dates, practise comparing old and new schedules. If you need help responding, prepare a short spoken summary or an email draft.',
    listening: [q('What should participants bring?',['An official certificate','An error log and two work samples','A payment card'],1,'Audioyêu cầuerrorlogvàtwoexamplesofwork.'),q('What is the review intended to do?',['Guarantee a score','Issue a certificate','Help plan next steps'],2,'Mụcđíchđịnhhướngbướctiếptheo,khôngcấpbằng.')],
    speaking: 'Tự tổng kết 60–90 giây: một điều đã luyện, một ví dụ lỗi còn gặp và hai bước tuần tới. Dùng hiện tại hoàn thành để nói quá trình, quá khứ đơn khi nêu bài đã làm ở thời điểm cụ thể. Không nêu điểm nếu chưa có kết quả thật.',
    assignment: 'Viết kế hoạch 120–150 từ dựa trên trải nghiệm học thực tế: nêu hai chiến lược đã thử, một lỗi có ví dụ, ba buổi tự học tuần tiếp theo và cách tự kiểm tra. Nếu chưa làm bài trong chương trình, viết rõ mục tiêu dự kiến thay vì khẳng định đã hoàn thành. Không tự tạo điểm hoặc chứng chỉ.',
    model: 'I plan to strengthen my workplace English by keeping a short error log and reviewing one topic at a time. My first priority is identifying revised dates in emails. I will compare the original time with the new time before choosing an answer. On Monday, I will review meeting vocabulary and practise two short messages. On Wednesday, I will listen to a notice twice and write its purpose, change and required action. On Saturday, I will write a brief email and check the greeting, request and closing. I will use actual feedback and my recorded mistakes to decide what to practise next. I will record a score only when a submitted task has a confirmed result.',
    quiz: [q('The team has _____ the review pack.',['prepare','preparing','prepared','prepares'],2,'Hiệntạihoànthànhhas+phântừprepared.'),q('We _____ the email yesterday.',['have read','read','have reading','has read'],1,'Yesterdaychỉthờiđiểmđãkếtthúc,dùngquákhứread.'),q('What is in the review pack?',['Only certificates','Emails, notices and meeting updates','Bank forms only','Travel tickets'],1,'Nộidungđọcnêucảbalọivănbản.'),q('What should an error log include?',['Only final scores','Reasons questions were difficult','Invented results','Other learners passwords'],1,'Ghilýdovìsaocâuhỏikhóvàvìsaosửađápán.'),q('What does the review NOT provide?',['Useful next steps','A chance for feedback','An official language certificate','Reading practice'],2,'Bàiđọcnóikhôngcấpchứngchỉngônngữchínhthức.'),q('Who should practise revised schedules?',['Those missing dates','Only instructors','All drivers','Those writing invoices'],0,'Ngườithườngmissdatesnênđốichiếulịchcũ/mới.'),q('Have you checked the list _____?',['yet','yesterday','ago','last'],0,'Yetphùhợpcâuhỏihiệntạihoànthành.'),q('Which statement is supported?',['Everyone has achieved a target score.','Feedback can inform future practice.','A certificate is guaranteed.','No work samples are needed.'],1,'Mụcđíchreviewlàfeedbackvànextsteps;khôngbảođảmđiểm.')],
  },
];

const reviewedExplanations = [
  ['Information là danh từ không đếm được; some dùng được với danh từ này.', 'Boxes đếm được số nhiều nên dùng a few; a little dùng với danh từ không đếm được.', 'Đơn đặt 20 thùng nhưng chỉ nhận 18, vì vậy còn thiếu 2 thùng.', 'Một chiếc ghế có tay vịn bị gãy; đèn đều ở tình trạng tốt.', 'Thư yêu cầu kiện hàng lớn đi qua cổng phụ, tức side gate.', 'Người gửi đính kèm ảnh món hỏng và bản sao phiếu giao hàng.', 'Câu hỏi với parts số nhiều dùng any để hỏi còn phụ tùng hay không.', 'Equipment không đếm được trong ngữ cảnh này; some equipment là cách dùng chuẩn.'],
  ['Sau could dùng động từ nguyên mẫu send, không có to hoặc đuôi -ing.', 'Do not have to có nghĩa không bắt buộc; người dùng vẫn có thể in nếu muốn.', 'Khách liên hệ vì tai nghe thay thế bị chậm, ảnh hưởng các cuộc họp trực tuyến.', 'Thư nhắc không gửi thông tin thẻ thanh toán; mã đơn và địa chỉ vẫn cần để xử lý.', 'Liên kết theo dõi được gửi sau khi đơn vị vận chuyển lấy bưu kiện.', 'Địa chỉ thay đổi cần được báo trước khi gửi hàng để tránh giao sai nơi.', 'Should theo sau bằng nguyên mẫu keep để diễn đạt lời khuyên.', 'Must not diễn đạt hành vi bị cấm; khác với do not have to là không bắt buộc.'],
  ['Trong điều kiện loại một cơ bản, mệnh đề if dùng hiện tại đơn: arrives.', 'Sau will dùng wait nguyên mẫu, không thêm s hoặc to.', 'Tàu khởi hành lúc 7:20 và đến lúc 9:05; cần phân biệt departure và arrival.', 'Hành khách cần đưa xác nhận đặt chỗ, tức reservation confirmation, cho tài xế.', 'Giá phòng bao gồm bữa sáng; văn bản nói bữa tối không được bao gồm.', 'Nếu tàu trễ hơn 20 phút, hành khách cần gọi khách sạn để hỏi chuyến xe tiếp theo.', 'Ngày trong tuần dùng on: on Wednesday.', 'Be going to theo sau bằng động từ nguyên mẫu visit.'],
  ['Thang máy chịu hành động kiểm tra nên dùng bị động hiện tại is inspected.', 'Bị động quá khứ có cấu trúc were + quá khứ phân từ: replaced.', 'Khoảng 8:00–12:00 thứ Bảy thuộc buổi sáng thứ Bảy.', 'Thang máy phía tây nhỏ hơn nên việc giao thiết bị lớn cần chuyển sang ngày khác.', 'Nhà thầu phải đăng ký tại quầy an ninh, tức security desk.', 'Nếu công việc kéo dài, bộ phận an ninh sẽ đăng cập nhật tại lễ tân.', 'Câu mệnh lệnh bắt đầu bằng động từ nguyên mẫu Keep.', 'Will be inspected nói về kế hoạch trong tương lai, chưa xác nhận đã hoàn thành.'],
  ['So sánh hơn của tính từ ngắn cheap là cheaper; không dùng more cheaper.', 'Sau more cần tính từ reliable để mô tả mức độ đáng tin cậy của dịch vụ.', 'ClearFile cung cấp 100 GB mỗi người; 70 GB là lượng sử dụng hiện tại.', 'Chỉ TeamArchive được mô tả có hỗ trợ buổi tối và cuối tuần.', 'Quản lý đề nghị thử ClearFile và xem xét lại sau ba tháng.', 'Cả hai dịch vụ đều có sao lưu tự động, vì vậy đây không phải điểm khác biệt.', 'So sánh hơn bất quy tắc của good là better.', 'Văn bản nêu có thể cân nhắc gói lớn hơn nếu lượng lưu trữ tăng.'],
  ['Because of theo sau bằng cụm danh từ repairs; because cần một mệnh đề.', 'Although nối hai mệnh đề có ý tương phản: phòng đổi nhưng giờ giữ nguyên.', 'Địa điểm mới là Seminar Room 3, thay cho hội trường tầng trệt.', 'Đăng ký bắt đầu lúc 9:00; workshop bắt đầu muộn hơn 30 phút, lúc 9:30.', 'Người tham dự cần vào bằng garden gate do khu vực cửa chính đang sửa chữa.', 'Người cần lối đi không có bậc thang phải liên hệ người tổ chức trước.', 'Therefore diễn đạt hệ quả: hội trường đóng nên dùng một phòng khác.', 'Thông báo nói bản in không cần thiết; có thể xuất trình email xác nhận trên điện thoại.'],
  ['Colleague chỉ người, nên mệnh đề quan hệ dùng who.', 'It thay cho Room Pine vì một căn phòng có sức chứa 16 người, còn máy chiếu thì không.', 'Nhóm có 12 người nhưng Oak chỉ chứa 10 người, vì vậy phòng quá nhỏ.', 'Email đầu yêu cầu khung giờ 13:00–15:00 thứ Ba.', 'Mạng không dây đang được nâng cấp; phòng vẫn có kết nối mạng dây.', 'Tin nhắn cuối chấp nhận Pine và cho biết người thuyết trình dùng được mạng dây.', 'Room chỉ vật nên dùng đại từ quan hệ which.', 'Có 12 người tham dự; con số 16 là sức chứa phòng, không phải số người được mời.'],
  ['Hiện tại hoàn thành có cấu trúc has + quá khứ phân từ: prepared.', 'Yesterday là thời điểm đã kết thúc, nên dùng quá khứ đơn read.', 'Bộ ôn tập có email, thông báo dịch vụ và cập nhật cuộc họp.', 'Nhật ký lỗi cần ghi vì sao câu hỏi khó và vì sao người học thay đổi câu trả lời.', 'Văn bản nêu rõ buổi ôn tập không cấp chứng chỉ ngôn ngữ chính thức.', 'Người hay bỏ sót ngày giờ nên luyện đối chiếu lịch ban đầu với lịch điều chỉnh.', 'Yet thường được dùng ở cuối câu hỏi hiện tại hoàn thành.', 'Phản hồi giúp chọn hoạt động luyện tiếp theo; văn bản không bảo đảm điểm hay chứng chỉ.'],
];
for (let i=4;i<units.length;i++) units[i].quiz.forEach((item,j)=>{item.explanation=reviewedExplanations[i-4][j];});
for (const u of units) u.listening.forEach(item=>{item.explanation=`Đáp án: ${item.options[item.correct]}. Đối chiếu đúng chi tiết trong bản chép lời; các lựa chọn còn lại chỉ nhắc lại từ trong tình huống hoặc sai thông tin được hỏi.`;});

function answers(items) { return items.map((item,i)=>`${i+1}. ${String.fromCharCode(65+item.correct)} — ${item.explanation}`).join('\n'); }
function questions(items) { return items.map((item,i)=>`${i+1}. ${item.prompt}\n${item.options.map((o,j)=>`${String.fromCharCode(65+j)}. ${o}`).join('\n')}`).join('\n\n'); }
function programmeDescription() { return 'Lộ trình TOEIC nền tảng 12 tuần, 12 học phần, 24 buổi học chính dự kiến, mỗi buổi 120 phút (48 giờ có hướng dẫn) và khoảng 36 giờ tự học. Trọng tâm Nghe–Đọc trong môi trường công sở, kết hợp thực hành giới thiệu, tóm tắt và viết email. Lịch từng lớp, quyền học, bài kiểm tra và kết quả được quản lý riêng; chương trình không cam kết điểm hoặc chứng chỉ.'; }
function lessons(unit, i) {
  const n=String(i+1).padStart(2,'0');
  return [
    { title: `${n}.1 · ${unit.grammar}`, skills:['READING'], minutes:45,
      markdown:`# ${unit.grammar}\n## Mục tiêu\n${unit.goals.map(g=>'- '+g).join('\n')}\n## Kiến thức trọng tâm\n${unit.notes.map((t,j)=>`${j+1}. ${t}`).join('\n')}\n## Ví dụ có phân tích\n${unit.examples.map(e=>'- '+e).join('\n')}\n## Từ vựng theo ngữ cảnh\n${unit.vocabulary.map(v=>'- '+v).join('\n')}\n## Thực hành có hướng dẫn\nViết lại ba câu ví dụ, thay một thông tin về người, thời gian hoặc địa điểm. Giữ đúng cấu trúc đang học. Đọc to từng câu và chỉ ra chủ ngữ, động từ, thông tin chính.\n## Tự kiểm tra\nChọn bốn câu trong phần đọc của bài tiếp theo. Gạch chân động từ và khoanh từ nối hoặc mốc thời gian. Giải thích vì sao cấu trúc đó phù hợp.\n## Tiêu chí hoàn thành\nGiải thích được ít nhất hai quy tắc, viết ba câu đúng cấu trúc, và sửa một lỗi của chính mình. Xem bài không tự tạo điểm hay bài nộp.` },
    { title:`${n}.2 · Đọc và nghe: ${unit.passageTitle}`,skills:['READING','LISTENING'],minutes:55,
      markdown:`# ${unit.passageTitle}\n## Trước khi đọc\nDự đoán nội dung từ tiêu đề. Tìm người viết/người nhận, mục đích và điều người nhận cần làm. Lập bảng ghi chú ba cột: sự kiện — thông tin cụ thể — bằng chứng trong bài.\n## Văn bản đọc nguyên bản\n${unit.reading}\n## Luyện nghe\nLần 1: nghe toàn bài, chỉ ghi mục đích. Lần 2: ghi số, giờ, nơi chốn và hành động. Lần 3 nếu cần: đối chiếu bản chép lời phía dưới. Đây là giọng đọc tổng hợp cục bộ dùng cho tự luyện; không phải bản ghi một buổi học đã diễn ra.\n\`\`\`audio\n/learning/toeic-foundation/unit-${n}.wav\n\`\`\`\n## Câu hỏi nghe\n${questions(unit.listening)}\n## Bản chép lời để đối chiếu sau khi nghe\n${unit.script}\n## Đáp án nghe và căn cứ\n${answers(unit.listening)}\n## Đọc lại chủ động\nTóm tắt đoạn đọc bằng ba câu tiếng Việt hoặc tiếng Anh. Nêu một chi tiết dễ nhầm và trích đúng câu làm bằng chứng. Không suy ra thông tin không có trong văn bản.` },
    { title:`${n}.3 · Vận dụng nói, viết và sửa lỗi`,skills:['SPEAKING','WRITING'],minutes:40,
      markdown:`# Vận dụng: ${unit.title}\n## Luyện nói\n${unit.speaking}\n## Quy trình 15 phút\n1. Chuẩn bị năm từ khóa, không viết nguyên bài để đọc.\n2. Nói một lượt, ghi lại chỗ dừng và từ chưa rõ.\n3. Nói lại, tập trung rõ ý và đúng cấu trúc, không cố nói nhanh.\n## Luyện viết\n${unit.assignment}\n## Bài tham khảo để phân tích\n${unit.model}\n## Tự đối chiếu\n- Nội dung: có đủ các ý được yêu cầu và số liệu đúng không?\n- Bố cục: lời mở, ý chính và kết thúc có dễ theo dõi không?\n- Ngôn ngữ: động từ, từ loại, giới từ và đại từ có nhất quán không?\n- Tính rõ ràng: người nhận biết cần làm gì và khi nào không?\n## Tiêu chí phản hồi\nĐáp ứng nhiệm vụ 40%; rõ ý và tổ chức 25%; độ chính xác ngôn ngữ 25%; từ vựng phù hợp 10%. Đây là hướng dẫn phản hồi, không phải điểm đã chấm. Bài nộp chính thức thực hiện ở hoạt động Bài tập, không dùng bài tham khảo làm bài của mình.` },
  ];
}

module.exports={units, q, lessons, questions, answers, programmeDescription};
